With(
    {wHoje: pHoje},
    With(
        {wSegunda: DateAdd(wHoje, 1 - Weekday(wHoje, StartOfWeek.Monday), TimeUnit.Days)},
        With(
            {wAno: Year(DateAdd(wSegunda, 3, TimeUnit.Days))},
            With(
                {wInicio: DateAdd(Date(wAno, 1, 4), 1 - Weekday(Date(wAno, 1, 4), StartOfWeek.Monday), TimeUnit.Days)},
                Text(wAno) & "-S" & Text(1 + RoundDown(DateDiff(wInicio, wSegunda, TimeUnit.Days) / 7, 0), "00")
            )
        )
    )
)

